 for(Object h:(List<?>)get(retr,"systemHeads"))call(h,"setLinker",Class.forName("org.audiveris.omr.sheet.stem.HeadLinker").getConstructor(Class.forName("org.audiveris.omr.sig.inter.HeadInter"),Class.forName("org.audiveris.omr.sheet.stem.StemsRetriever")).newInstance(h,retr));
 for(Object b:(List<?>)get(retr,"systemBeams"))call(call(b,"getLinker"),"inspectVLinkers");
 List<Object>corners=new ArrayList<>();for(Object h:(List<?>)get(retr,"systemHeads"))for(Object hc:(Object[])Class.forName("org.audiveris.omr.sheet.stem.HeadCorner").getMethod("values").invoke(null)){Object c=call(call(h,"getLinker"),"getCornerLinker",get(hc,"hSide"),get(hc,"vSide"));call(c,"inspect",call(call(sheet,"getStub"),"getProfile"));corners.add(c);}
 // Every opposite builder exists before expansion. No linkStems/finalizeStems.
